"use strict";
function row(id, name, email) {
  const profile = { id: id, name: name };
  if (email !== null) profile.email = email;
  return profile;
}
function loadProfiles() {
  return [row(1, "ada", "ada@example.com"), row(2, "guest", null), row(3, "lin", "lin@example.com")];
}
function findProfile(id) {
  return loadProfiles().find((p) => p.id === id);
}
exports.loadProfiles = loadProfiles;
exports.findProfile = findProfile;
